-- evt:plug
RegisterEvent(23, "Bronze plug", function()
    if not (IsAtLeast(ActualMight, 30) and not (IsQBitSet(QBit(110640)))) then
        if IsQBitSet(QBit(110640)) then evt.StatusText("The plug hangs free on its chain. Below the window the reservoir lies empty.") else evt.StatusText("You aren't strong enough to pull the plug. A stronger arm, or a potion of Might, might shift it.", 6) end
        return
    end
    evt.SetDoorState(9, DoorAction.Open)
    evt.SetDoorState(10, DoorAction.Open)
    evt.SetDoorState(1, DoorAction.Open)
    evt.SetDoorState(2, DoorAction.Open)
    evt.SetDoorState(3, DoorAction.Open)
    evt.SetDoorState(11, DoorAction.Open)
    SetQBit(QBit(110640))
    evt.PlaySoundName("xeen_reservoir_drain", 2048, 2944, 0)
    evt.SimpleMessage("You set your feet and heave on the chain. The bronze plug comes up out of its pool with a sucking roar, and through the window the black water of the reservoir begins to sink. The water roars away down the sump; somewhere below, stone gates grind open.")
end, "Bronze plug")

